package dev.orca.pocket.tests;
import android.app.*;import android.content.*;import android.os.*;import android.webkit.WebView;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.*;
/** Optional native Android -> real Windows desktop acknowledgement acceptance. */
public final class WindowsDeviceSmoke extends Instrumentation {
 private boolean waitingTask; private WebView web; private String app="doubao",marker="WIN-ANDROID-DOUBAO-20261009-1858";
 @Override public void onCreate(Bundle args){super.onCreate(args);if(args!=null){app=args.getString("app",app);marker=args.getString("marker",marker);}if(!app.matches("doubao|workbuddy")||!marker.matches("[A-Z0-9-]{1,100}"))throw new IllegalArgumentException("Invalid acceptance target");start();}
 private String js(String code)throws Exception {CountDownLatch done=new CountDownLatch(1);String[] value={null};runOnMainSync(()->web.evaluateJavascript(code,v->{value[0]=v;done.countDown();}));if(!done.await(10,TimeUnit.SECONDS))throw new Exception("JS timeout");return value[0];}
 private void until(String predicate,int seconds)throws Exception {long end=System.currentTimeMillis()+seconds*1000;while(System.currentTimeMillis()<end){if("true".equals(js(predicate)))return;if(waitingTask&&"true".equals(js("!!document.querySelector('.status.failed')")))throw new Exception("Desktop failed: "+js("document.body.innerText.slice(-1200)"));Thread.sleep(500);}throw new Exception("Timeout: "+predicate+" UI="+js("document.body.innerText.slice(-1200)"));}
 private byte[] asset(String name)throws Exception {try(InputStream in=getContext().getAssets().open(name)){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] data=new byte[4096];int n;while((n=in.read(data))>0)b.write(data,0,n);return b.toByteArray();}}
 private Activity launch()throws Exception {Activity activity=startActivitySync(new Intent().setClassName("dev.orca.pocket","dev.orca.pocket.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Field f=activity.getClass().getDeclaredField("web");f.setAccessible(true);web=(WebView)f.get(activity);until("typeof receive==='function'",20);return activity;}
 @Override public void onStart(){Bundle result=new Bundle();try{
  Activity activity=launch();Field key=activity.getClass().getDeclaredField("privateKey");key.setAccessible(true);key.set(activity,asset("client"));Field store=activity.getClass().getDeclaredField("store");store.setAccessible(true);Object vault=store.get(activity);Method put=vault.getClass().getDeclaredMethod("put",String.class,String.class);put.setAccessible(true);put.invoke(vault,"host:[10.0.2.2]:22993",new String(asset("fingerprint"),"UTF-8").trim());
  js("document.getElementById('connectionButton').click();document.getElementById('host').value='10.0.2.2';document.getElementById('port').value='22993';document.getElementById('user').value='Administrator';document.getElementById('connect').click();");until("connected&&state.agents.some(a=>a.id==='"+app+"')&&!busy",120);
  waitingTask=true;js("startConversation();state.profile.accessMode='desktop';state.selected='"+app+"';updateSelection();document.getElementById('input').value='这是 Android 到 Windows 云电脑的链路验收，请不要使用工具，仅回复 "+marker+"';document.getElementById('input').dispatchEvent(new Event('input'));document.getElementById('send').click();");
  until("!busy&&state.messages.some(m=>m.role==='assistant'&&m.status==='已完成'&&m.text==='"+marker+"')",180);waitingTask=false;Thread.sleep(1200);
  android.graphics.Bitmap shot=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"windows-"+app+".png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}shot.recycle();
  runOnMainSync(activity::finish);Thread.sleep(500);launch();until("state.messages.some(m=>m.role==='assistant'&&m.status==='已完成'&&m.text==='"+marker+"')",30);
  result.putString("stream","PASS signed Android APK -> JSch -> SFTP -> real Windows interactive bridge -> "+app+" received acknowledgement -> native chat completion -> persisted reply after reopening.\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL "+e.toString()+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
